package org.sleepwell.app;

import org.junit.Test;
import java.io.*;
import java.util.concurrent.atomic.*;
import static org.junit.Assert.*;

public class CloudBackupCopyTest {
    private static final class Fake implements CloudBackupCopy.Provider {int creates,writes,reads,cancels;byte[] saved;boolean corrupt,deny,empty;final CloudBackupCopy.Document doc=new CloudBackupCopy.Document("content://fixture/new-version","new.json");public CloudBackupCopy.Document create(String name){creates++;return doc;}public OutputStream output(CloudBackupCopy.Document d)throws IOException{writes++;if(deny)throw new IOException("denied");return new ByteArrayOutputStream(){public void close(){saved=toByteArray();}};}public InputStream input(CloudBackupCopy.Document d){reads++;return empty?new InputStream(){public int read(){return 0;}public int read(byte[] b){return 0;}}:new ByteArrayInputStream(corrupt?new byte[]{1,2,3}:saved);}public void cancel(){cancels++;}}
    @Test public void createsThenWritesAndReadBackVerifiesExactBytes()throws Exception{Fake f=new Fake();byte[] bytes="{\"format\":6,\"note\":\"Private\"}".getBytes(java.nio.charset.StandardCharsets.UTF_8);AtomicBoolean created=new AtomicBoolean();CloudBackupCopy.Receipt receipt=CloudBackupCopy.save(active->bytes,f,"version.json",()->true,doc->{assertEquals(0,f.writes);created.set(true);});assertTrue(created.get());assertEquals(1,f.creates);assertEquals(1,f.writes);assertEquals(1,f.reads);assertArrayEquals(bytes,f.saved);assertEquals(bytes.length,receipt.size);assertEquals(CloudBackupCopy.sha(bytes),receipt.sha);}
    @Test public void invalidOrOversizedSnapshotCannotCreateRemoteFile()throws Exception{for(byte[] bytes:new byte[][]{new byte[0],new byte[BackupIo.LIMIT+1]}){Fake f=new Fake();try{CloudBackupCopy.save(active->bytes,f,"version",()->true,d->{});fail();}catch(IOException expected){}assertEquals(0,f.creates);}}
    @Test public void cancelledSnapshotNeverOpensProvider()throws Exception{Fake f=new Fake();try{CloudBackupCopy.save(active->new byte[]{1},f,"version",()->false,d->{});fail();}catch(InterruptedIOException expected){}assertEquals(0,f.creates);}
    @Test public void cancellationAfterCreationKeepsVersionButNeverWrites()throws Exception{Fake f=new Fake();AtomicBoolean active=new AtomicBoolean(true);try{CloudBackupCopy.save(a->new byte[]{1},f,"version",active::get,d->active.set(false));fail();}catch(InterruptedIOException expected){}assertEquals(1,f.creates);assertEquals(0,f.writes);}
    @Test public void writeDenialCannotProduceVerifiedReceipt()throws Exception{Fake f=new Fake();f.deny=true;AtomicInteger created=new AtomicInteger();try{CloudBackupCopy.save(a->new byte[]{1},f,"version",()->true,d->created.incrementAndGet());fail();}catch(IOException expected){}assertEquals(1,created.get());assertEquals(0,f.reads);}
    @Test public void mismatchedOrStalledReadBackIsRejected()throws Exception{for(boolean corrupt:new boolean[]{true,false}){Fake f=new Fake();f.corrupt=corrupt;f.empty=!corrupt;try{CloudBackupCopy.save(a->new byte[]{8,9,10},f,"version",()->true,d->{});fail();}catch(IOException expected){}assertArrayEquals(new byte[]{8,9,10},f.saved);}}
    @Test public void sourceFailureCannotCreateFile()throws Exception{Fake f=new Fake();try{CloudBackupCopy.save(a->{throw new IOException("snapshot");},f,"version",()->true,d->{});fail();}catch(IOException expected){}assertEquals(0,f.creates);}
    @Test public void providerMustReturnAnAndroidDocument()throws Exception{CloudBackupCopy.Provider bad=new CloudBackupCopy.Provider(){public CloudBackupCopy.Document create(String name){return new CloudBackupCopy.Document("https://example.org","remote");}public OutputStream output(CloudBackupCopy.Document d){throw new AssertionError();}public InputStream input(CloudBackupCopy.Document d){throw new AssertionError();}public void cancel(){}};try{CloudBackupCopy.save(a->new byte[]{1},bad,"version",()->true,d->{});fail();}catch(IOException expected){}}
}
